export const CreateBackupResponse = zod.object({
  "id": zod.string(),
  "status": zod.enum(['running', 'completed', 'failed']),
  "startedAt": zod.coerce.date(),
  "endedAt": zod.coerce.date().nullable(),
  "filePath": zod.string().nullable(),
  "sizeBytes": zod.number().nullable(),
  "errorMessage": zod.string().nullable()
})


/**
 * DESTRUCTIVE — overwrites the current database with the backup's contents.
 */
export const RestoreBackupEndpointBody = zod.object({
  "id": zod.string().describe('backup_runs.id from GET \/backups — NOT a filesystem path. The server looks up the real file path itself; a client can only pick which recorded backup to restore, never point pg_restore at an arbitrary file.'),
  "confirm": zod.boolean().describe('must be true — a lightweight guard against an accidental restore call, mirroring the CLI\'s --yes flag')
})

export const RestoreBackupEndpointResponse = zod.unknown()


